1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.ContextoCupom;
4	import com.loja.checkout.domain.Cupom;
5	import com.loja.checkout.domain.FormaPagamento;
6	import com.loja.checkout.domain.Item;
7	import com.loja.checkout.domain.ModalidadeEntrega;
8	import com.loja.checkout.domain.Money;
9	import com.loja.checkout.domain.NivelClube;
10	import com.loja.checkout.domain.PedidoInvalidoException;
11	import com.loja.checkout.domain.Regiao;
12	import com.loja.checkout.domain.ResultadoPagamento;
13	import com.loja.checkout.web.CheckoutRequest;
14	import com.loja.checkout.web.ItemRequest;
15	import com.loja.checkout.web.ResumoResponse;
16	import java.math.BigDecimal;
17	import java.util.List;
18	import org.springframework.stereotype.Service;
19	
20	/**
21	 * Calcula o resumo da compra. Confere os problemas na ordem definida pelo
22	 * enunciado (devolvendo o primeiro encontrado) e só então monta o resumo.
23	 */
24	@Service
25	public class CalculadoraResumo {
26	
27	    public ResumoResponse calcular(CheckoutRequest req) {
28	        // 1. Itens
29	        List<Item> itens = validarItens(req.itens());
30	        BigDecimal subtotal = Money.centavos(somar(itens, Item::subtotal));
31	        BigDecimal peso = somar(itens, Item::peso);
32	
33	        // 2. Clube  3. Região  4. Modalidade
34	        NivelClube clube = exigir(NivelClube.class, req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
35	        Regiao regiao = exigir(Regiao.class, req.regiao(), "REGIAO_INVALIDA");
36	        ModalidadeEntrega modalidade = exigir(ModalidadeEntrega.class, req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
37	
38	        // 5. Modalidade atende o pedido?
39	        if (!modalidade.disponivel(peso)) {
40	            throw new PedidoInvalidoException("MODALIDADE_INDISPONIVEL");
41	        }
42	        BigDecimal frete = Money.centavos(clube.aplicarIsencao(modalidade.frete(peso)));
43	
44	        // 6. Cupom existe?  7. Cupom aplicável?
45	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
46	        if (req.cupom() != null) {
47	            Cupom cupom = analisar(Cupom.class, req.cupom());
48	            if (cupom == null) {
49	                throw new PedidoInvalidoException("CUPOM_INVALIDO");
50	            }
51	            ContextoCupom ctx = new ContextoCupom(subtotal, frete, itens);
52	            if (!cupom.aplicavel(ctx)) {
53	                throw new PedidoInvalidoException("CUPOM_NAO_APLICAVEL");
54	            }
55	            descontoCupom = Money.centavos(cupom.desconto(ctx));
56	        }
57	
58	        // 8. Pagamento existe?  9. Parcelas permitidas?
59	        FormaPagamento pagamento = exigir(FormaPagamento.class, req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
60	        int parcelas = req.parcelas() == null ? 1 : req.parcelas();
61	        if (!pagamento.parcelasValidas(parcelas)) {
62	            throw new PedidoInvalidoException("PARCELAMENTO_INVALIDO");
63	        }
64	
65	        BigDecimal seguro = Money.centavos(subtotal.multiply(regiao.percentualSeguro()));
66	        BigDecimal totalPedido = Money.centavos(
67	                subtotal.subtract(descontoCupom).add(frete).add(seguro));
68	
69	        // 10. Pagamento atende o total?
70	        if (!pagamento.disponivel(totalPedido)) {
71	            throw new PedidoInvalidoException("FORMA_PAGAMENTO_INDISPONIVEL");
72	        }
73	
74	        ResultadoPagamento resultado = pagamento.calcula(totalPedido, parcelas);
75	        BigDecimal ajuste = resultado.totalFinal().subtract(totalPedido);
76	
77	        return new ResumoResponse(
78	                subtotal,
79	                descontoCupom,
80	                frete,
81	                modalidade.prazoDias(),
82	                seguro,
83	                ajuste,
84	                resultado.totalFinal(),
85	                parcelas,
86	                resultado.valorParcela(),
87	                clube.credito(subtotal),
88	                clube.temBrinde(subtotal));
89	    }
90	
91	    private List<Item> validarItens(List<ItemRequest> itens) {
92	        if (itens == null || itens.isEmpty()) {
93	            throw new PedidoInvalidoException("PEDIDO_INVALIDO");
94	        }
95	        return itens.stream().map(this::validarItem).toList();
96	    }
97	
98	    private Item validarItem(ItemRequest i) {
99	        if (i == null || !positivo(i.precoUnitario()) || i.quantidade() == null
100	                || i.quantidade() <= 0 || !positivo(i.pesoKg())) {
101	            throw new PedidoInvalidoException("PEDIDO_INVALIDO");
102	        }
103	        return new Item(i.nome(), i.precoUnitario(), i.quantidade(), i.pesoKg());
104	    }
105	
106	    private boolean positivo(BigDecimal valor) {
107	        return valor != null && valor.compareTo(BigDecimal.ZERO) > 0;
108	    }
109	
110	    private BigDecimal somar(List<Item> itens, java.util.function.Function<Item, BigDecimal> parcela) {
111	        return itens.stream().map(parcela).reduce(BigDecimal.ZERO, BigDecimal::add);
112	    }
113	
114	    /** Converte texto no enum, ou lança o código informado se não existir/estiver ausente. */
115	    private <E extends Enum<E>> E exigir(Class<E> tipo, String valor, String codigoErro) {
116	        E resultado = analisar(tipo, valor);
117	        if (resultado == null) {
118	            throw new PedidoInvalidoException(codigoErro);
119	        }
120	        return resultado;
121	    }
122	
123	    /** Converte texto no enum, ou devolve null se for nulo ou não existir. */
124	    private <E extends Enum<E>> E analisar(Class<E> tipo, String valor) {
125	        if (valor == null) {
126	            return null;
127	        }
128	        try {
129	            return Enum.valueOf(tipo, valor);
130	        } catch (IllegalArgumentException e) {
131	            return null;
132	        }
133	    }
134	}
