1	package com.loja.checkout.domain;
2	
3	import java.math.BigDecimal;
4	
5	/**
6	 * Cupons de desconto. Cada cupom guarda no seu próprio bloco a regra do desconto
7	 * e a condição para poder ser usado. Para uma promoção nova, basta mais uma
8	 * constante aqui.
9	 */
10	public enum Cupom {
11	
12	    /** 10% sobre o valor dos produtos. */
13	    BEMVINDO10 {
14	        @Override
15	        public BigDecimal desconto(ContextoCupom ctx) {
16	            return ctx.subtotalProdutos().multiply(new BigDecimal("0.10"));
17	        }
18	    },
19	    /** R$ 50,00 de desconto, só a partir de R$ 300,00 em produtos. */
20	    MENOS50 {
21	        @Override
22	        public BigDecimal desconto(ContextoCupom ctx) {
23	            return new BigDecimal("50.00");
24	        }
25	
26	        @Override
27	        public boolean aplicavel(ContextoCupom ctx) {
28	            return ctx.subtotalProdutos().compareTo(new BigDecimal("300.00")) >= 0;
29	        }
30	    },
31	    /** Zera o frete: o desconto é igual ao frete que aparece no resumo. */
32	    FRETEGRATIS {
33	        @Override
34	        public BigDecimal desconto(ContextoCupom ctx) {
35	            return ctx.frete();
36	        }
37	    },
38	    /** A cada 3 unidades de um mesmo item, uma sai de graça. */
39	    LEVE3PAGUE2 {
40	        @Override
41	        public BigDecimal desconto(ContextoCupom ctx) {
42	            return ctx.itens().stream()
43	                    .map(item -> item.precoUnitario().multiply(BigDecimal.valueOf(item.unidadesGratis())))
44	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
45	        }
