1	package com.loja.checkout.domain;
2	
3	import java.math.BigDecimal;
4	
5	/**
6	 * Formas de pagamento. Cada forma define, no seu próprio bloco, quais
7	 * parcelamentos aceita, quando está disponível e como o pagamento muda o valor
8	 * final do pedido.
9	 */
10	public enum FormaPagamento {
11	
12	    /** À vista, 5% de desconto sobre o total do pedido. */
13	    PIX {
14	        @Override
15	        public boolean parcelasValidas(int parcelas) {
16	            return parcelas == 1;
17	        }
18	
19	        @Override
20	        public ResultadoPagamento calcula(BigDecimal totalPedido, int parcelas) {
21	            BigDecimal desconto = Money.centavos(totalPedido.multiply(new BigDecimal("0.05")));
22	            BigDecimal totalFinal = totalPedido.subtract(desconto);
23	            return new ResultadoPagamento(totalFinal, totalFinal);
24	        }
25	    },
26	    /** À vista, com tarifa bancária de R$ 3,49. Não aceito acima de R$ 1.000,00. */
27	    BOLETO {
28	        @Override
29	        public boolean parcelasValidas(int parcelas) {
30	            return parcelas == 1;
31	        }
32	
33	        @Override
34	        public boolean disponivel(BigDecimal totalPedido) {
35	            return totalPedido.compareTo(new BigDecimal("1000.00")) <= 0;
36	        }
37	
38	        @Override
39	        public ResultadoPagamento calcula(BigDecimal totalPedido, int parcelas) {
40	            BigDecimal totalFinal = totalPedido.add(new BigDecimal("3.49"));
41	            return new ResultadoPagamento(totalFinal, totalFinal);
42	        }
43	    },
44	    /** De 1 a 12x: até 3x sem juros; de 4x a 12x com juros de 1,99% ao mês (tabela Price). */
45	    CARTAO {
46	        private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
47	
48	        @Override
49	        public boolean parcelasValidas(int parcelas) {
50	            return parcelas >= 1 && parcelas <= 12;
51	        }
52	
53	        @Override
54	        public ResultadoPagamento calcula(BigDecimal totalPedido, int parcelas) {
55	            if (parcelas <= 3) {
56	                BigDecimal valorParcela = totalPedido.divide(
57	                        BigDecimal.valueOf(parcelas), 2, java.math.RoundingMode.HALF_EVEN);
58	                return new ResultadoPagamento(totalPedido, valorParcela);
59	            }
60	            double taxa = TAXA_MENSAL.doubleValue();
61	            double fator = taxa / (1 - Math.pow(1 + taxa, -parcelas));
62	            BigDecimal valorParcela = Money.centavos(
63	                    BigDecimal.valueOf(totalPedido.doubleValue() * fator));
64	            BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
65	            return new ResultadoPagamento(totalFinal, valorParcela);
66	        }
67	    };
68	
69	    /** Se o número de parcelas é permitido para esta forma. */
70	    public abstract boolean parcelasValidas(int parcelas);
71	
72	    /** Valor final e valor da parcela a partir do total do pedido. */
73	    public abstract ResultadoPagamento calcula(BigDecimal totalPedido, int parcelas);
74	
75	    /** Se a forma atende um pedido deste total. Por padrão, atende. */
76	    public boolean disponivel(BigDecimal totalPedido) {
77	        return true;
78	    }
79	}
