3	import java.math.BigDecimal;
4	
5	/**
6	 * Níveis do clube. Hoje as vantagens variam só em valores e flags: quanto de
7	 * crédito o cliente ganha, se é isento de frete e a partir de que valor de
8	 * produtos ganha brinde (nulo = nunca). Por isso são dados, não comportamento.
9	 */
10	public enum NivelClube {
11	
12	    BRONZE("0", false, null),
13	    PRATA("0.02", false, null),
14	    OURO("0.05", true, "500.00");
15	
16	    private final BigDecimal creditoPercentual;
17	    private final boolean isentaFrete;
18	    private final BigDecimal limiteBrinde;
19	
20	    NivelClube(String creditoPercentual, boolean isentaFrete, String limiteBrinde) {
21	        this.creditoPercentual = new BigDecimal(creditoPercentual);
22	        this.isentaFrete = isentaFrete;
23	        this.limiteBrinde = limiteBrinde == null ? null : new BigDecimal(limiteBrinde);
24	    }
25	
26	    /** Crédito para a próxima compra sobre o valor dos produtos (arredondado). */
27	    public BigDecimal credito(BigDecimal subtotalProdutos) {
28	        return Money.centavos(subtotalProdutos.multiply(creditoPercentual));
29	    }
30	
31	    /** Frete que o cliente paga: zero quando o nível é isento. */
32	    public BigDecimal aplicarIsencao(BigDecimal frete) {
33	        return isentaFrete ? BigDecimal.ZERO : frete;
34	    }
35	
36	    /** Se o pedido ganha brinde, conforme o valor dos produtos. */
37	    public boolean temBrinde(BigDecimal subtotalProdutos) {
38	        return limiteBrinde != null && subtotalProdutos.compareTo(limiteBrinde) > 0;
39	    }
40	}
